    },
    {
      "dsl": "strength(\"n_inquiries\") in (\"negligible\", \"weak\")",
      "sentence_id": 6
    },
    {
      "dsl": "strength(\"months_at_address\") in (\"negligible\", \"weak\")",
      "sentence_id": 6
    },
    {
      "dsl": "negligible(\"age\")",
      "sentence_id": 6
    },
    {
      "dsl": "interaction(\"utilization\", \"n_delinquencies\", pattern=\"amplification\")",
      "sentence_id": 7
    }
  ],
  "sentences": [
    {
      "id": 1,
      "text": "Revolving credit utilization is the single most important driver of default risk, and the risk generally increases as utilization rises."
    },
    {
      "id": 2,
      "text": "The number of past delinquencies is the second most important feature, with a moderate to strong effect that increases default risk as delinquencies accumulate."
    },
    {
      "id": 3,
      "text": "Annual income is the third or fourth most important feature, exerting a moderate effect as risk generally decreases with higher income."
    },
    {
      "id": 4,
      "text": "Credit history length is also the third or fourth most important feature, with a moderate effect where risk generally decreases as the history lengthens."
    },
    {
      "id": 5,
      "text": "The debt-to-income ratio is the fifth most important feature, and it has a weak to moderate effect on default risk as it generally increases."
    },
    {
      "id": 6,
      "text": "The remaining features, including credit inquiries, months at address, and age, contribute at most a weak effect or hardly matter to the model."
    },
    {
      "id": 7,
      "text": "The effect of revolving credit utilization on default risk grows significantly when the applicant has a higher number of past delinquencies."
    }
  ]
}

